import type { StudioLibKey } from '../../studio/contract';

/**
 * Pixi Studio asset texts (DESIGN §B.1), loaded lazily — pixi-studio:runtime-wiring (2026-10-10).
 *
 * Each add-on library is its own IIFE asset generated by `engine-libs`
 * (`scripts/build-studio-engines.mjs` → `engines/studio/<key>-source.ts`, exporting
 * `<KEY>_SOURCE` with its banner) and the sound engine by `sound-engine`
 * (`engines/studio/sound-source.ts`, `SOUND_SOURCE`). Every asset installs itself on
 * `window.ckEngines` (`ready('lib-<key>', …)` / `ready('sound', …)`).
 *
 * The generated modules are reached ONLY through the `import()` calls below, so none of them can
 * reach the editor's main chunk (held by `inject.test.ts`); the canvas injector (`inject.ts`), the
 * exporter and the Studio preview document all read them through this one table.
 */
export type StudioEngineKind = `lib-${StudioLibKey}` | 'sound';

export const STUDIO_ENGINE_LOADERS: Readonly<Record<StudioEngineKind, () => Promise<string>>> = {
  'lib-kit': async () => (await import('./kit-source')).KIT_SOURCE,
  'lib-filters': async () => (await import('./filters-source')).FILTERS_SOURCE,
  'lib-emitter': async () => (await import('./emitter-source')).EMITTER_SOURCE,
  'lib-physics': async () => (await import('./physics-source')).PHYSICS_SOURCE,
  'lib-brush': async () => (await import('./brush-source')).BRUSH_SOURCE,
  'lib-rough': async () => (await import('./rough-source')).ROUGH_SOURCE,
  'lib-viewport': async () => (await import('./viewport-source')).VIEWPORT_SOURCE,
  'lib-anim': async () => (await import('./anim-source')).ANIM_SOURCE,
  'lib-fx': async () => (await import('./fx-source')).FX_SOURCE,
  'lib-dialogue': async () => (await import('./dialogue-source')).DIALOGUE_SOURCE,
  'lib-ink': async () => (await import('./ink-source')).INK_SOURCE,
  'lib-tilemap': async () => (await import('./tilemap-source')).TILEMAP_SOURCE,
  'lib-audio': async () => (await import('./audio-source')).AUDIO_SOURCE,
  'lib-gameai': async () => (await import('./gameai-source')).GAMEAI_SOURCE,
  'lib-hud': async () => (await import('./hud-source')).HUD_SOURCE,
  'lib-peeps': async () => (await import('./peeps-source')).PEEPS_SOURCE,
  'lib-procgen': async () => (await import('./procgen-source')).PROCGEN_SOURCE,
  'lib-gif': async () => (await import('./gif-source')).GIF_SOURCE,
  'lib-noise': async () => (await import('./noise-source')).NOISE_SOURCE,
  'lib-geom': async () => (await import('./geom-source')).GEOM_SOURCE,
  'lib-hex': async () => (await import('./hex-source')).HEX_SOURCE,
  'lib-color': async () => (await import('./color-source')).COLOR_SOURCE,
  'lib-lsys': async () => (await import('./lsys-source')).LSYS_SOURCE,
  sound: async () => (await import('./sound-source')).SOUND_SOURCE,
};

/** The asset file each Studio engine publishes as (`assets/ck-lib-<key>.js`, `assets/ck-sound.js`). */
export function studioAssetFile(kind: StudioEngineKind): string {
  return `ck-${kind}.js`;
}
